def order(api, customer_id, *items):
    return api.orders.handle_create({"customer_id": customer_id,
                                     "items": [{"sku": s, "quantity": q} for s, q in items]})


def test_customers_without_orders_all_when_no_orders(shop):
    response = shop.insights.handle_customers_without_orders()
    assert response.status == 200
    assert response.body == {"customers": [
        {"customer_id": "c1", "name": "Ada", "email": "ada@example.com"},
        {"customer_id": "c2", "name": "Grace", "email": "grace@example.com"},
    ]}


def test_customers_without_orders_excludes_customers_with_active_orders(shop):
    order(shop, "c1", ("PEN", 1))
    response = shop.insights.handle_customers_without_orders()
    assert [c["customer_id"] for c in response.body["customers"]] == ["c2"]


def test_customers_with_only_cancelled_orders_are_included(shop):
    cancelled = order(shop, "c1", ("PEN", 1)).body["order_id"]
    shop.orders.handle_cancel(cancelled)
    response = shop.insights.handle_customers_without_orders()
    assert [c["customer_id"] for c in response.body["customers"]] == ["c1", "c2"]


def test_customers_without_orders_empty_when_all_have_orders(shop):
    order(shop, "c1", ("PEN", 1))
    order(shop, "c2", ("PEN", 1))
    response = shop.insights.handle_customers_without_orders()
    assert response.body == {"customers": []}


def test_customers_without_orders_in_registration_order(shop):
    shop.customers.handle_register({"customer_id": "a0", "name": "Zed", "email": "z@example.com"})
    response = shop.insights.handle_customers_without_orders()
    assert [c["customer_id"] for c in response.body["customers"]] == ["c1", "c2", "a0"]

